from collections import deque

def count_components_in_block(grid, r_start, c_start):
    """Count connected components of 1s in a specific block"""
    components = 0
    visited = set()

    def bfs(start_r, start_c):
        comp_cells = set()
        queue = deque([(start_r, start_c)])
        comp_cells.add((start_r, start_c))
        visited.add((start_r, start_c))

        while queue:
            r, c = queue.popleft()
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < 7 and 0 <= nc < 7:
                    if grid[nr][nc] == 1 and (nr, nc) not in visited:
                        visited.add((nr, nc))
                        comp_cells.add((nr, nc))
                        queue.append((nr, nc))
        return comp_cells

    # Scan each cell in the block
